    return (
        self.filename == other.filename
        and self.line_number == other.line_number
        and self.col_number == other.col_number
        and self.problem == other.problem
    )

def flake8(file_path: str) -> str:
    """Run flake8 on a given file and return the output as a string"""
    if Path(file_path).suffix != ".py":
        return ""
    cmd = "flake8 --isolated --select=F821,F822,F831,E111,E112,E113,E999,E902 {file_path}"
    out = subprocess.run(
        cmd.format(file_path=file_path), shell=True, check=False, capture_output=True
    )
    # Use errors="replace" so non-UTF-8 bytes (e.g. GBK-encoded paths on Windows) don't crash decoding.
    return out.stdout.decode("utf-8", errors="replace")

class EditTool:
    """
    An filesystem editor tool that allows the agent to view, create, and edit files.
    The tool parameters are defined by Anthropic and are not editable.
    """

    name = "str_replace_editor"

    def __init__(self, REGISTRY, absolute_docs_path=None):
        super().__init__()
        self._encoding = None
        self.REGISTRY = REGISTRY
        self.logs = []
        self.absolute_docs_path = Path(absolute_docs_path) if absolute_docs_path else None

    def _get_display_path(self, path: Path) -> str:
        """Get path for display purposes - relative to absolute_docs_path if available"""
        if self.absolute_docs_path and path.is_absolute():
            try:
                return str(path.relative_to(self.absolute_docs_path))
            except ValueError:
                # Path is not under absolute_docs_path, return as-is
                return str(path)
        return str(path)

    @property
    def _file_history(self):
        return defaultdict(list, json.loads(self.REGISTRY.get("file_history", "{}")))

    @_file_history.setter
    def _file_history(self, value: dict):
        self.REGISTRY["file_history"] = json.dumps(value)

    def __call__(
        self,
        *,
        command: Command,
        path: str,
        file_text: str | None = None,
        view_range: list[int] | None = None,
        old_str: str | None = None,
        new_str: str | None = None,
        insert_line: int | None = None,
        **kwargs,
    ):
        _path = Path(path)
        if not self.validate_path(command, _path):
            return
        if command == "view":
            return self.view(_path, view_range)
        elif command == "create":
            if file_text is None:
                self.logs.append("Parameter `file_text` is required for command: create")
                return
            self.create_file(_path, file_text)
            return None
        elif command == "str_replace":
            if old_str is None:
                self.logs.append("Parameter `old_str` is required for command: str_replace")
                return
            return self.str_replace(_path, old_str, new_str)
        elif command == "insert":
            if insert_line is None:
                self.logs.append("Parameter `insert_line` is required for command: insert")
                return
            if new_str is None:
                self.logs.append("Parameter `new_str` is required for command: insert")
                return
            return self.insert(_path, insert_line, new_str)
        elif command == "undo_edit":
            return self.undo_edit(_path)
        self.logs.append(
            f'Unrecognized command {command}. The allowed commands for the {self.name} tool are: "view", "create", "str_replace", "insert", "undo_edit"'
        )
        return

    def validate_path(self, command: str, path: Path):
        """
        Check that the path/command combination is valid.
        """
        # Check if its an absolute path
        if not path.is_absolute():
            suggested_path = Path.cwd() / path
            self.logs.append(
                f"The path {self._get_display_path(path)} is not an absolute path, it should start with `/`. Maybe you meant {self._get_display_path(suggested_path)}?"
            )
            return False
        # Check if path exists
        if not path.exists() and command != "create":
            self.logs.append(
                f"The path {self._get_display_path(path)} does not exist. Please provide a valid path."
            )
            return False
        if path.exists() and command == "create":
            self.logs.append(
                f"File already exists at: {self._get_display_path(path)}. Cannot overwrite files using command `create`."
            )
            return False
        # Check if the path points to a directory
        if path.is_dir() and command != "view":
            self.logs.append(
                f"The path {self._get_display_path(path)} is a directory and only the `view` command can be used on directories"
            )
            return False
        return True

    def create_file(self, path: Path, file_text: str):
        if not path.parent.exists():
            self.logs.append(
                f"The parent directory {self._get_display_path(path.parent)} does not exist. Please create it first."
            )
            return
        self.write_file(path, file_text)
        self._file_history[path].append(file_text)
        self.logs.append(f"File created successfully at: {self._get_display_path(path)}")

    def view(self, path: Path, view_range: list[int] | None = None):
        """Implement the view command"""
        if path.is_dir():
            if view_range:
                self.logs.append(
                    "The `view_range` parameter is not allowed when `path` points to a directory."
                )
                return

            # Hidden entries are skipped except `.github` (CI workflows are
            # documentation-relevant artifacts the agent must be able to find).
            out = subprocess.run(
                rf"find {shlex.quote(str(path))} -maxdepth 2 "
                r"\( -not -path '*/.*' -o -name .github -o -path '*/.github/*' \)",
                shell=True,
                check=False,
                capture_output=True,
            )
            # Use errors="replace" so non-UTF-8 bytes (e.g. GBK-encoded filenames on Windows) don't crash decoding.
            stdout = out.stdout.decode("utf-8", errors="replace")
            stderr = out.stderr.decode("utf-8", errors="replace")

            if not stderr:
                stdout = stdout.replace(str(path), self._get_display_path(path))
                stdout = f"Here's the files and directories up to 2 levels deep in {self._get_display_path(path)}, excluding hidden items (except .github):\n{stdout}\n"
                self.logs.append(stdout)
            return

        file_content = self.read_file(path)
        if view_range:
            if len(view_range) != 2 or not all(isinstance(i, int) for i in view_range):
                self.logs.append("Invalid `view_range`. It should be a list of two integers.")
                return
            file_lines = file_content.split("\n")
            n_lines_file = len(file_lines)
            init_line, final_line = view_range
            if init_line < 1 or init_line > n_lines_file:
                self.logs.append(
                    f"Invalid `view_range`: {view_range}. Its first element `{init_line}` should be within the range of lines of the file: {[1, n_lines_file]}"
                )
                return
            if final_line > n_lines_file:
                self.logs.append(
                    f"Invalid `view_range`: {view_range}. Its second element `{final_line}` should be smaller than the number of lines in the file: `{n_lines_file}`"
                )
                return
            if final_line != -1 and final_line < init_line:
                self.logs.append(
                    f"Invalid `view_range`: {view_range}. Its second element `{final_line}` should be larger or equal than its first `{init_line}`"
                )
                return

            if final_line == -1:
                final_line = n_lines_file

            # Expand the viewport to include the whole function or class
            init_line, final_line = WindowExpander(suffix=path.suffix).expand_window(
                file_lines, init_line, final_line, max_added_lines=MAX_WINDOW_EXPANSION_VIEW
            )

            file_content = "\n".join(file_lines[init_line - 1 : final_line])
        else:
            if path.suffix == ".py" and len(file_content) > MAX_RESPONSE_LEN and USE_FILEMAP:
                try:
                    filemap = Filemap().show_filemap(
                        file_content, encoding=self._encoding or "utf-8"
                    )
                except Exception:  # noqa: BLE001, S110 — filemap is optional
                    # If we fail to show the filemap, just show the truncated file content
                    pass
                else:
                    self.logs.append(
                        "<NOTE>This file is too large to display entirely. Showing abbreviated version. "
                        "Please use `str_replace_editor view` with the `view_range` parameter to show selected lines next.</NOTE>"
                    )
                    filemap = maybe_truncate(filemap.expandtabs())
                    self.logs.append(filemap)
                    self.logs.append(
                        "<IMPORTANT><NOTE>The above file has been abbreviated. Please use `str_replace editor view` with `view_range` to look at relevant files in detail.</NOTE></IMPORTANT>"
                    )
                    return
            # Else just show
            init_line = 1

        # init_line is 1-based
        self.logs.append(
            self._make_output(file_content, self._get_display_path(path), init_line=init_line)
        )

    def str_replace(self, path: Path, old_str: str, new_str: str | None):
        """Implement the str_replace command, which replaces old_str with new_str in the file content"""
        # Read the file content
        file_content = self.read_file(path).expandtabs()
        old_str = old_str.expandtabs()
        new_str = new_str.expandtabs() if new_str is not None else ""

        # Check if old_str is unique in the file
        occurrences = file_content.count(old_str)
        if occurrences == 0:
            self.logs.append(
                f"No replacement was performed, old_str `{old_str}` did not appear verbatim in {self._get_display_path(path)}."
            )
            return
        elif occurrences > 1:
            file_content_lines = file_content.split("\n")
            lines = [idx + 1 for idx, line in enumerate(file_content_lines) if old_str in line]
            self.logs.append(
                f"No replacement was performed. Multiple occurrences of old_str `{old_str}` in lines {lines}. Please ensure it is unique"
            )
            return

        if new_str == old_str:
            self.logs.append(
                f"No replacement was performed, old_str `{old_str}` is the same as new_str `{new_str}`."
            )
            return

        pre_edit_lint = ""
        if USE_LINTER:
            try:
                pre_edit_lint = flake8(str(path))
            except Exception as e:  # noqa: BLE001 — linting must never block an edit
                self.logs.append(f"Warning: Failed to run pre-edit linter on {path}: {e}")

        # Replace old_str with new_str
        new_file_content = file_content.replace(old_str, new_str)

        # Write the new content to the file
        self.write_file(path, new_file_content)

        post_edit_lint = ""
        if USE_LINTER:
            try:
                post_edit_lint = flake8(str(path))
            except Exception as e:  # noqa: BLE001 — linting must never block an edit
                self.logs.append(f"Warning: Failed to run post-edit linter on {path}: {e}")

        epilogue = ""
        if post_edit_lint:
            replacement_window_start_line = file_content.split(old_str)[0].count("\n") + 1
            replacement_lines = len(new_str.split("\n"))
            replacement_window_end_line = replacement_window_start_line + replacement_lines - 1
            replacement_window = (replacement_window_start_line, replacement_window_end_line)
            errors = format_flake8_output(
                post_edit_lint,
                previous_errors_string=pre_edit_lint,
                replacement_window=replacement_window,
                replacement_n_lines=replacement_lines,
            )
            if errors.strip():
                epilogue = LINT_WARNING_TEMPLATE.format(errors=errors)

        # Save the content to history
        self._file_history[path].append(file_content)

        # Create a snippet of the edited section
        replacement_line = file_content.split(old_str)[0].count("\n")
        start_line = max(1, replacement_line - SNIPPET_LINES)
        end_line = min(
            replacement_line + SNIPPET_LINES + new_str.count("\n"),
            len(new_file_content.splitlines()),
        )
        start_line, end_line = WindowExpander(suffix=path.suffix).expand_window(
            new_file_content.split("\n"),
            start_line,
            end_line,
            max_added_lines=MAX_WINDOW_EXPANSION_EDIT_CONFIRM,
        )
        snippet = "\n".join(new_file_content.split("\n")[start_line - 1 : end_line])

        # Prepare the success message
        success_msg = f"The file {self._get_display_path(path)} has been edited. "
        success_msg += self._make_output(
            snippet, f"a snippet of {self._get_display_path(path)}", start_line
        )
        success_msg += "Review the changes and make sure they are as expected. Edit the file again if necessary."
        success_msg += epilogue

        self.logs.append(success_msg)

    def insert(self, path: Path, insert_line: int, new_str: str):
        """Implement the insert command, which inserts new_str at the specified line in the file content."""
        file_text = self.read_file(path).expandtabs()
        new_str = new_str.expandtabs()
        file_text_lines = file_text.split("\n")
        n_lines_file = len(file_text_lines)

        if insert_line < 0 or insert_line > n_lines_file:
            self.logs.append(
                f"Invalid `insert_line` parameter: {insert_line}. It should be within the range of lines of the file: {[0, n_lines_file]}"
            )
            return

        new_str_lines = new_str.split("\n")
        new_file_text_lines = (
            file_text_lines[:insert_line] + new_str_lines + file_text_lines[insert_line:]
        )
        snippet_lines = (
            file_text_lines[max(0, insert_line - SNIPPET_LINES) : insert_line]
            + new_str_lines
            + file_text_lines[insert_line : insert_line + SNIPPET_LINES]
        )

        new_file_text = "\n".join(new_file_text_lines)
        snippet = "\n".join(snippet_lines)

        self.write_file(path, new_file_text)
        self._file_history[path].append(file_text)

        # todo: Also expand these windows

        success_msg = f"The file {self._get_display_path(path)} has been edited. "
        success_msg += self._make_output(
            snippet,
            "a snippet of the edited file",
            max(1, insert_line - SNIPPET_LINES + 1),
        )
        success_msg += "Review the changes and make sure they are as expected (correct indentation, no duplicate lines, etc). Edit the file again if necessary."
        self.logs.append(success_msg)

    def undo_edit(self, path: Path):
        """Implement the undo_edit command."""
        if not self._file_history[path]:
            self.logs.append(f"No edit history found for {self._get_display_path(path)}.")
            return

        old_text = self._file_history[path].pop()
        self.write_file(path, old_text)

        self.logs.append(
            f"Last edit to {self._get_display_path(path)} undone successfully. {self._make_output(old_text, self._get_display_path(path))}"
        )

    def read_file(self, path: Path):
        """Read the content of a file from a given path; raise a ToolError if an error occurs."""
        encodings = [
            (None, None),
            ("utf-8", None),
            ("latin-1", None),
            ("utf-8", "replace"),
        ]
        exception = None
        for self._encoding, errors in encodings:
            try:
                text = path.read_text(encoding=self._encoding, errors=errors)
            except UnicodeDecodeError as e:
                exception = e
            else:
                break
        else:
            self.logs.append(
                f"Ran into UnicodeDecodeError {exception} while trying to read {self._get_display_path(path)}"
            )
            return
        return text

    def write_file(self, path: Path, file: str):
        """Write the content of a file to a given path; raise a ToolError if an error occurs."""
        try:
            path.write_text(file, encoding=self._encoding or "utf-8")
        except Exception as e:  # noqa: BLE001 — reported to the agent as a tool message
            self.logs.append(
                f"Ran into {e} while trying to write to {self._get_display_path(path)}"
            )
            return

    def _make_output(
        self,
        file_content: str,
        file_descriptor: str,
        init_line: int = 1,
        expand_tabs: bool = True,
    ):
        """Generate output for the CLI based on the content of a file."""
        file_content = maybe_truncate(file_content)
        if expand_tabs:
            file_content = file_content.expandtabs()
        file_content = "\n".join(
            [f"{i + init_line:6}\t{line}" for i, line in enumerate(file_content.split("\n"))]
        )
        return (
            f"Here's the result of running `cat -n` on {file_descriptor}:\n" + file_content + "\n"
        )

def _get_display_path(self, path: Path) -> str:
    """Get path for display purposes - relative to absolute_docs_path if available"""
    if self.absolute_docs_path and path.is_absolute():
        try:
            return str(path.relative_to(self.absolute_docs_path))
        except ValueError:
            # Path is not under absolute_docs_path, return as-is
            return str(path)
    return str(path)

def __call__(
    self,
    *,
    command: Command,
    path: str,
    file_text: str | None = None,
    view_range: list[int] | None = None,
    old_str: str | None = None,
    new_str: str | None = None,
    insert_line: int | None = None,
    **kwargs,
):
    _path = Path(path)
    if not self.validate_path(command, _path):
        return
    if command == "view":
        return self.view(_path, view_range)
    elif command == "create":
        if file_text is None:
            self.logs.append("Parameter `file_text` is required for command: create")
            return
        self.create_file(_path, file_text)
        return None
    elif command == "str_replace":
        if old_str is None:
            self.logs.append("Parameter `old_str` is required for command: str_replace")
            return
        return self.str_replace(_path, old_str, new_str)
    elif command == "insert":
        if insert_line is None:
            self.logs.append("Parameter `insert_line` is required for command: insert")
            return
        if new_str is None:
            self.logs.append("Parameter `new_str` is required for command: insert")
            return
        return self.insert(_path, insert_line, new_str)
    elif command == "undo_edit":
        return self.undo_edit(_path)
    self.logs.append(
        f'Unrecognized command {command}. The allowed commands for the {self.name} tool are: "view", "create", "str_replace", "insert", "undo_edit"'
    )
    return

def validate_path(self, command: str, path: Path):
    """
    Check that the path/command combination is valid.
    """
    # Check if its an absolute path
    if not path.is_absolute():
        suggested_path = Path.cwd() / path
        self.logs.append(
            f"The path {self._get_display_path(path)} is not an absolute path, it should start with `/`. Maybe you meant {self._get_display_path(suggested_path)}?"
        )
        return False
    # Check if path exists
    if not path.exists() and command != "create":
        self.logs.append(
            f"The path {self._get_display_path(path)} does not exist. Please provide a valid path."
        )
        return False
    if path.exists() and command == "create":
        self.logs.append(
            f"File already exists at: {self._get_display_path(path)}. Cannot overwrite files using command `create`."
        )
        return False
    # Check if the path points to a directory
    if path.is_dir() and command != "view":
        self.logs.append(
            f"The path {self._get_display_path(path)} is a directory and only the `view` command can be used on directories"
        )
        return False
    return True

def create_file(self, path: Path, file_text: str):
    if not path.parent.exists():
        self.logs.append(
            f"The parent directory {self._get_display_path(path.parent)} does not exist. Please create it first."
        )
        return
    self.write_file(path, file_text)
    self._file_history[path].append(file_text)
    self.logs.append(f"File created successfully at: {self._get_display_path(path)}")

def undo_edit(self, path: Path):
    """Implement the undo_edit command."""
    if not self._file_history[path]:
        self.logs.append(f"No edit history found for {self._get_display_path(path)}.")
        return

    old_text = self._file_history[path].pop()
    self.write_file(path, old_text)

    self.logs.append(
        f"Last edit to {self._get_display_path(path)} undone successfully. {self._make_output(old_text, self._get_display_path(path))}"
    )

def read_file(self, path: Path):
    """Read the content of a file from a given path; raise a ToolError if an error occurs."""
    encodings = [
        (None, None),
        ("utf-8", None),
        ("latin-1", None),
        ("utf-8", "replace"),
    ]
    exception = None
    for self._encoding, errors in encodings:
        try:
            text = path.read_text(encoding=self._encoding, errors=errors)
        except UnicodeDecodeError as e:
            exception = e
        else:
            break
    else:
        self.logs.append(
            f"Ran into UnicodeDecodeError {exception} while trying to read {self._get_display_path(path)}"
        )
        return
    return text

def write_file(self, path: Path, file: str):
    """Write the content of a file to a given path; raise a ToolError if an error occurs."""
    try:
        path.write_text(file, encoding=self._encoding or "utf-8")
    except Exception as e:  # noqa: BLE001 — reported to the agent as a tool message
        self.logs.append(
            f"Ran into {e} while trying to write to {self._get_display_path(path)}"
        )
        return

def _make_output(
    self,
    file_content: str,
    file_descriptor: str,
    init_line: int = 1,
    expand_tabs: bool = True,
):
    """Generate output for the CLI based on the content of a file."""
    file_content = maybe_truncate(file_content)
    if expand_tabs:
        file_content = file_content.expandtabs()
    file_content = "\n".join(
        [f"{i + init_line:6}\t{line}" for i, line in enumerate(file_content.split("\n"))]
    )
    return (
        f"Here's the result of running `cat -n` on {file_descriptor}:\n" + file_content + "\n"
    )

def check_write_allowed(absolute_path: str, allowed: "set[str] | None") -> str | None:
    """Return an error message when ``absolute_path`` is outside the write set.

    ``allowed`` holds absolute paths; both sides are resolved so symlinks and
    ``..`` segments cannot slip a write past the guard. ``None`` means the
    agent may write anywhere under its working dir (normal generation).
    """
    if allowed is None:
        return None
    try:
        resolved = str(Path(absolute_path).resolve())
    except OSError:
        resolved = os.path.abspath(absolute_path)
    allowed_resolved = set()
    for a in allowed:
        try:
            allowed_resolved.add(str(Path(a).resolve()))
        except OSError:
            allowed_resolved.add(os.path.abspath(a))
    if resolved in allowed_resolved:
        return None
    names = sorted(os.path.basename(a) for a in allowed_resolved)
    return (
        f"Error: {os.path.basename(absolute_path)!r} is not in this agent's write set. "
        f"You may only edit these pages: {names}. Everything else must stay untouched; "
        f"if it needs a change, say so in your final verdict instead."
    )

