def _first_sentence(text: str | None) -> str:
    if not text:
        return ""
    for line in text.splitlines():
        s = line.strip()
        if not s or s.startswith("#") or s.startswith("```") or s.startswith("|"):
            continue
        return s[:160]
    return ""

