def node_at(tree: dict[str, Any], path: Path) -> dict[str, Any] | None:
    level = tree
    info: dict[str, Any] | None = None
    for i, name in enumerate(path):
        if not isinstance(level, dict) or name not in level:
            return None
        info = level[name]
        if i < len(path) - 1:
            level = info.get("children", {})
    return info

